import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"Working with Bots","description":"","frontmatter":{},"headers":[],"relativePath":"guides/working-with-bots.md","filePath":"guides/working-with-bots.md","lastUpdated":1790952322000}'),r={name:"guides/working-with-bots.md"};function n(i,e,l,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="working-with-bots" tabindex="-1">Working with Bots <a class="header-anchor" href="#working-with-bots" aria-label="Permalink to &quot;Working with Bots&quot;">​</a></h1><p><a href="./quick-start.html">Quick Start</a> gets a bot running; this page is about working with one well — what to delegate, how to phrase it, where rules should live, and when one bot should become two — followed by the configuration reference: creating a bot and every tab on its detail page.</p><h2 id="what-to-hand-off" tabindex="-1">What to hand off <a class="header-anchor" href="#what-to-hand-off" aria-label="Permalink to &quot;What to hand off&quot;">​</a></h2><p>A task is a good fit for a bot when three things hold:</p><ul><li><strong>A clear outcome.</strong> You can say what should exist when the work is done — a file, a message, a table.</li><li><strong>Reachable sources.</strong> The files, sites, or conversations involved are ones the bot can actually get to: uploaded into its workspace, connected as a channel or service, or public.</li><li><strong>A checkable result.</strong> You can tell at a glance whether the output is right, so reviewing stays cheap.</li></ul><p>When all three hold, start read-only anyway: let the bot read and organize first, review a few outputs, then grant more. Every scenario in <a href="./use-cases.html">Use Cases</a> begins this way.</p><h2 id="state-the-request" tabindex="-1">State the request <a class="header-anchor" href="#state-the-request" aria-label="Permalink to &quot;State the request&quot;">​</a></h2><p>A good request answers five questions — outcome, source, constraints, format, checkpoint. The table is in <a href="./quick-start.html#step-4-give-it-a-task">Quick Start</a>; here is what the difference looks like in practice.</p><div class="warning custom-block"><p class="custom-block-title">Vague</p><blockquote><p>Keep an eye on tech news and send me anything interesting.</p></blockquote></div><p>No source (which sites or repositories?), no delivery time, and &quot;interesting&quot; is a judgment the bot has to make for you. Every digest becomes a coin flip.</p><p><strong>Instead:</strong></p><div class="tip custom-block"><p class="custom-block-title">Specific</p><blockquote><p>Every weekday at 8am, summarize releases and notable issues from the repositories I follow over the last 24 hours, and send them to me as one digest. Cite a source for every item; if something is uncertain, say so instead of guessing.</p></blockquote></div><div class="warning custom-block"><p class="custom-block-title">Vague</p><blockquote><p>Clean up this spreadsheet.</p></blockquote></div><p>&quot;Clean&quot; is undefined: which rows count as dirty, may the original file change, and what should come back? The bot has to guess three times before it starts.</p><p><strong>Instead:</strong></p><div class="tip custom-block"><p class="custom-block-title">Specific</p><blockquote><p>Remove every row with an empty email column from the CSV I just uploaded. Give me the cleaned file and tell me how many rows you dropped. Do not modify the original file.</p></blockquote></div><p>The pattern in both rewrites: name the sources, bound the actions, and make the result something you can verify in one look.</p><h2 id="where-rules-live" tabindex="-1">Where rules live <a class="header-anchor" href="#where-rules-live" aria-label="Permalink to &quot;Where rules live&quot;">​</a></h2><p>Two kinds of instruction, two homes:</p><ul><li><strong>Permanent rules</strong> belong in the bot&#39;s instructions on its detail page — its role, format standards, standing constraints. They apply to every future session.</li><li><strong>One-off asks</strong> belong in the message — today&#39;s file, this week&#39;s exception.</li></ul><p>When a correction should stick, promote it: phrase it as a durable rule and move it into the instructions, exactly as <a href="./quick-start.html#step-7-review-then-make-it-stick">Quick Start</a> step 7 shows. When a whole routine repeats, save it as a <a href="./skills.html">Skill</a> so one sentence invokes it; preferences the bot should recall on its own belong in <a href="./memory.html">Memory</a>.</p><h2 id="when-to-split-bots" tabindex="-1">When to split bots <a class="header-anchor" href="#when-to-split-bots" aria-label="Permalink to &quot;When to split bots&quot;">​</a></h2><p>One bot, one job. A bot with a single focused job accumulates context that keeps helping it; a do-everything bot dilutes its own instructions and memory. Both <a href="./quick-start.html">Quick Start</a> and the <a href="./overview.html">Overview</a> make the same point, so here is only the practical test: when a new request has a different audience, different sources, or needs different permissions than the bot&#39;s current job, create a second bot.</p><p>Each bot gets its own workspace, memory, channels, and permission boundary, and bots cannot see into each other. Splitting also keeps permissions honest — the bot that only reads release notes never needs the right to execute commands.</p><h2 id="approval-habits" tabindex="-1">Approval habits <a class="header-anchor" href="#approval-habits" aria-label="Permalink to &quot;Approval habits&quot;">​</a></h2><p>Grant the level a job needs and no more — workspace access is tiered from chat through read, write, execute, and manage; see <a href="./access.html">Access Control</a>.</p><p>In practice:</p><ol><li>Start new routines read-only and keep write and execute tool calls behind approval.</li><li>Review the first few runs before widening anything.</li><li>Keep actions that leave the workspace — messages to other people, anything external — behind approval even after the routine feels safe.</li></ol><p>This is the same path the <a href="./use-cases.html#from-example-to-routine">Use Cases</a> checklist walks: approving a few requests costs far less than undoing a wrong write.</p><hr><h2 id="creating-a-bot" tabindex="-1">Creating a Bot <a class="header-anchor" href="#creating-a-bot" aria-label="Permalink to &quot;Creating a Bot&quot;">​</a></h2><ol><li>Navigate to the <strong>Bots</strong> page from the sidebar.</li><li>Click the <strong>Create Bot</strong> button.</li><li>Fill in the basic info: <ul><li><strong>Display Name</strong>: The name users will see in chats.</li><li><strong>Avatar</strong>: A URL for the bot&#39;s profile picture.</li><li><strong>Timezone</strong>: Optional per-bot timezone. If left empty, the bot inherits the user or system timezone.</li><li><strong>ACL Preset</strong>: Quick-start access policy such as <code>allow_all</code> or <code>private_only</code>.</li></ul></li><li>Click <strong>Create</strong>.</li></ol><hr><h2 id="bot-detail-page" tabindex="-1">Bot Detail Page <a class="header-anchor" href="#bot-detail-page" aria-label="Permalink to &quot;Bot Detail Page&quot;">​</a></h2><p>Once created, clicking on a bot card takes you to its <strong>Detail Page</strong>, where you can manage its entire lifecycle through specialized tabs.</p><h3 id="tab-overview" tabindex="-1">Tab Overview <a class="header-anchor" href="#tab-overview" aria-label="Permalink to &quot;Tab Overview&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tab</th><th>Description</th></tr></thead><tbody><tr><td><strong>Overview</strong></td><td>Health checks for workspace runtime, database, channels, and memory.</td></tr><tr><td><strong>General</strong></td><td>Core runtime settings: chat/title/image models, memory/search/TTS bindings, timezone, language, reasoning, and danger zone.</td></tr><tr><td><strong>Desktop</strong></td><td>Workspace display runtime, headed browser availability, and active display sessions.</td></tr><tr><td><strong>Workspace</strong></td><td>Container-backed workspace lifecycle, snapshots, data export/import.</td></tr><tr><td><strong>Network</strong></td><td>Workspace network and overlay provider status/actions.</td></tr><tr><td><strong>Memory</strong></td><td>Browse, search, create, edit, and compact memories.</td></tr><tr><td><strong>Platforms</strong></td><td>Channel configurations such as Telegram, Discord, Feishu, QQ, WeCom, WeChat, DingTalk, and Web.</td></tr><tr><td><strong>Access</strong></td><td>ACL rules and default access behavior.</td></tr><tr><td><strong>Tool Approval</strong></td><td>Human approval settings for tools that require confirmation.</td></tr><tr><td><strong>Agents</strong></td><td>ACP-compatible coding agents, such as Codex and Claude Code, that can be enabled for chat workspace use.</td></tr><tr><td><strong>Connectors</strong></td><td>Third-party service connections (OAuth or API key) via Connect-It: status, enable/disable, reauthorize, disconnect.</td></tr><tr><td><strong>Hooks</strong></td><td>Bot-scoped automation rules stored in <code>/data/.memoh/hooks.json</code>.</td></tr><tr><td><strong>MCP</strong></td><td>MCP connection management (Stdio, Remote, OAuth).</td></tr><tr><td><strong>Compaction</strong></td><td>Session context compaction settings and logs.</td></tr><tr><td><strong>Schedule</strong></td><td>Cron-based scheduled tasks and execution logs.</td></tr><tr><td><strong>Skills</strong></td><td>Markdown-based skill files that define bot personality and capabilities.</td></tr></tbody></table><p>Files, Terminal, and the desktop/browser panes are also available inside the chat workspace UI — use the workspace side of a chat when you want to inspect files, run shell commands, or watch the bot&#39;s browser and desktop without leaving the conversation.</p><hr><h2 id="configuring-the-bot-s-core-settings" tabindex="-1">Configuring the Bot&#39;s Core Settings <a class="header-anchor" href="#configuring-the-bot-s-core-settings" aria-label="Permalink to &quot;Configuring the Bot&#39;s Core Settings&quot;">​</a></h2><p>After creating a bot, the most important step is configuring its runtime settings. These settings are split across a few tabs instead of living in one giant form.</p><ol><li>Navigate to your bot&#39;s <strong>Detail Page</strong>.</li><li>Start with the <strong>General</strong> tab for chat/runtime bindings.</li><li>Use the <strong>Schedule</strong> tab for recurring autonomous tasks.</li><li>Use the <strong>Compaction</strong> tab for session context compaction behavior.</li><li>Use the <strong>Access</strong> tab to refine ACL rules after the initial ACL preset.</li></ol><p>If you have not created these resources yet, set them up first:</p><ul><li><a href="./../integrations/providers/llm.html">Providers And Models</a></li><li><a href="./../integrations/providers/memory/builtin.html">Built-in Memory Provider</a></li><li><a href="./../integrations/providers/web-search.html">Search Providers</a></li><li><a href="./../integrations/providers/tts/edge.html">TTS: Edge</a></li><li><a href="./acp.html">Agents / ACP</a></li></ul><hr><h2 id="general-tab-reference" tabindex="-1">General Tab Reference <a class="header-anchor" href="#general-tab-reference" aria-label="Permalink to &quot;General Tab Reference&quot;">​</a></h2><p>The <strong>General</strong> tab contains the settings that shape everyday conversation behavior.</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Chat Model</strong></td><td>The main LLM used for generating chat responses.</td></tr><tr><td><strong>Title Model</strong></td><td>Optional model used to generate session titles.</td></tr><tr><td><strong>Image Generation Model</strong></td><td>Optional model used by image-generation features. Pick a chat model that supports <code>image-output</code>.</td></tr><tr><td><strong>Memory Provider</strong></td><td>The memory backend assigned to the bot. The built-in provider can optionally define its own memory and embedding models.</td></tr><tr><td><strong>Search Provider</strong></td><td>The search engine used for web browsing capabilities.</td></tr><tr><td><strong>TTS Model</strong></td><td>Optional speech model used for text-to-speech output. Speech models come from the TTS Providers flow, not the normal chat provider flow.</td></tr><tr><td><strong>Timezone</strong></td><td>Per-bot timezone. If empty, Memoh inherits the user timezone and then falls back to the system timezone.</td></tr><tr><td><strong>Language</strong></td><td>The bot&#39;s primary communication language.</td></tr><tr><td><strong>Reasoning Effort</strong></td><td>Available when the selected chat model exposes <code>reasoning</code> compatibility. Options depend on the model (for example <code>low</code>, <code>medium</code>, <code>high</code>).</td></tr></tbody></table><p>Notes:</p><ul><li>The <strong>Image Generation Model</strong> is intentionally separate from the normal chat model so you can dedicate an image-capable model only to visual generation tasks.</li><li>The <strong>TTS Model</strong> comes from the <a href="./../integrations/providers/tts/edge.html">TTS provider</a> flow and uses <code>speech</code> models from the configured speech provider.</li><li>The selected chat model&#39;s <code>context_window</code> influences session status reporting and <a href="./compaction.html">Context Compaction</a>.</li></ul><hr><h2 id="compaction-tab-reference" tabindex="-1">Compaction Tab Reference <a class="header-anchor" href="#compaction-tab-reference" aria-label="Permalink to &quot;Compaction Tab Reference&quot;">​</a></h2><p>Compaction is now about <strong>session context compaction</strong>, not memory maintenance.</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Compaction Enabled</strong></td><td>Enable or disable automatic context compaction.</td></tr><tr><td><strong>Compaction Threshold</strong></td><td>Estimated token threshold that triggers compaction.</td></tr><tr><td><strong>Compaction Ratio</strong></td><td>How aggressively the session context should be reduced.</td></tr><tr><td><strong>Compaction Model</strong></td><td>Optional dedicated model used to summarize old session context.</td></tr></tbody></table><p>The Compaction tab also exposes compaction logs so you can see recent successful, pending, or failed runs.</p><p>For the runtime behavior, see <a href="./compaction.html">Context Compaction</a>.</p><hr><h2 id="access-and-acl" tabindex="-1">Access And ACL <a class="header-anchor" href="#access-and-acl" aria-label="Permalink to &quot;Access And ACL&quot;">​</a></h2><p>At creation time, the bot starts from an <strong>ACL preset</strong>. After that, use the <strong>Access</strong> tab for fine-grained control.</p><p>Two layers matter:</p><ul><li><strong>ACL Preset</strong> gives you a sensible starting policy for a new bot.</li><li><strong>ACL Default Effect</strong> controls the default result when no rule matches.</li></ul><p>Use the <strong>Access</strong> tab to refine conversation, group, and thread rules after the initial setup.</p><hr><h2 id="discuss-related-advanced-settings" tabindex="-1">Discuss-Related Advanced Settings <a class="header-anchor" href="#discuss-related-advanced-settings" aria-label="Permalink to &quot;Discuss-Related Advanced Settings&quot;">​</a></h2><p>Most users only need the <code>chat</code> and <code>discuss</code> behavior described in <a href="./sessions.html">Sessions</a>.</p><p>If you manage bot settings through the API or custom automation, the settings schema also includes <code>discuss_probe_model_id</code> for discuss-mode specific setups. Treat it as an advanced setting rather than a required field for normal bot creation.</p><hr><h2 id="workspace-files-and-terminal" tabindex="-1">Workspace Files And Terminal <a class="header-anchor" href="#workspace-files-and-terminal" aria-label="Permalink to &quot;Workspace Files And Terminal&quot;">​</a></h2><p>Workspace files and terminals are available from the chat workspace UI after the bot has an active workspace runtime. From there you can:</p><ul><li>Browse and edit files in the bot workspace.</li><li>Open terminal sessions inside the workspace runtime.</li><li>Use display/browser tools when the bot workspace has display support enabled.</li></ul><p>For file workflows, see <a href="./files.html">Files</a>. For headed browser and desktop workflows, see <a href="./browser-computer-use.html">Browser / Computer Use</a>.</p><hr><h2 id="deleting-a-bot" tabindex="-1">Deleting a Bot <a class="header-anchor" href="#deleting-a-bot" aria-label="Permalink to &quot;Deleting a Bot&quot;">​</a></h2><p>To permanently remove a bot and all its associated data (including workspace files and memory):</p><ol><li>Navigate to the <strong>General</strong> tab in the Bot Detail page.</li><li>Scroll to the <strong>Danger Zone</strong> at the bottom.</li><li>Click <strong>Delete Bot</strong> and confirm the action.</li></ol><blockquote><p><strong>Warning</strong>: This action is irreversible. All persistent data for this bot will be lost.</p></blockquote>',76)])])}const u=t(r,[["render",n]]);export{p as __pageData,u as default};
